import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"K54","description":"","frontmatter":{"title":"K54"},"headers":[],"relativePath":"general/k54.md","filePath":"general/k54.md","lastUpdated":null}'),o={name:"general/k54.md"};function s(i,e,c,l,d,u){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="k54" tabindex="-1">K54 <a class="header-anchor" href="#k54" aria-label="Permalink to &quot;K54&quot;">​</a></h1><h2 id="k54-1" tabindex="-1">K54 <a class="header-anchor" href="#k54-1" aria-label="Permalink to &quot;K54&quot;">​</a></h2><p>k&gt;fivefour is a private sector focused cybersecurity affiliate of Millennium Corporation, a defense contractor and cybersecurity company which delivers a full range of products, services, and solutions to the Department of Defense (DoD) and other federal agencies.</p><p>k&gt;fivefour leverages Millennium’s specialized technical expertise serving the DoD Red Team community, where they execute hundreds of cybersecurity assessments for 2 of the 9 National Security Agency (NSA) certified and U.S. Cyber Command (USCYBERCOM) accredited Full Spectrum Red Teams.</p><p>Having professionals who have developed their unique skills emulating the most sophisticated nation-state cyber adversaries has allowed k&gt;fivefour to deliver an unprecedented level of training services and cybersecurity solutions to our clients. k&gt;fivefour assimilates the most current knowledge on the latest advanced cyber threats and maintains a deep understanding of adversarial tactics and techniques. Leveraging our team’s extensive experience in the DoD space, k&gt;fivefour brings an unparalleled level of ability to assess organizations’ security posture and help defend against cyber-attacks.. [# K54 Training ## Red Team Apprentice Course (RTAC)</p><p>Students learn and prepare for starting a career emulating nation-state level cyber threats and adversaries. The exclusive Red Team Apprentice Course is the first course in a three-course series. Successful completion of the Red Team Apprentice Course is required before enrolling in the Red Team Journeyman™ Course (RTJC) or the Red Team Master™ Course (RTMC).</p><p>In the Red Team Apprentice Course, students learn how adversaries accomplish high-profile attacks. The course is continuously updated and built around the most recent intelligence on nation-state level cyber-attacks and adversaries found in open source, industry threat reports.</p><p>This course follows an attack methodology that mimics the structure of nation-state hackers. Students learn over 5 days in a guided, hands-on lab driven network attack scenario, utilizing a purpose-built training environment, and each student conducts a Red Team operation against a simulated Microsoft® Windows® domain network. The course concludes with an optional practical certification exam to test the knowledge gained in the course. ## Red Team Journeyman Course (RTJC) This class is two weeks in length (Monday-Friday for each week)</p><p>This exclusive Red Team Journeyman Course is the second course in a three-course series. Students must obtain the Red Team Apprentice Operator designation before enrolling in the Red Team Journeyman Course.</p><p>This course follows k&gt;five four’s attack methodology which mimics the structure of nation-state hackers. Over 8 class days, students are guided through a hands-on, lab driven network attack scenario, utilizing our purpose-built training environment. The course concludes with a practical 2-day hands on certification exam to test the knowledge gained in the course.</p><p>Students passing this exam are certified k&gt;five four “Red Team Journeyman” operators and receive a certificate and personalized operator identification card.[3] # POC enter content here</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><p><a href="https://kfivefour.com/" target="_blank" rel="noreferrer">https://kfivefour.com/</a></p></li><li><p><a href="https://store.k54.com/collections/all-courses/products/red-team-apprentice-course-rtac-3" target="_blank" rel="noreferrer">https://store.k54.com/collections/all-courses/products/red-team-apprentice-course-rtac-3</a></p></li><li><p><a href="https://store.k54.com/collections/all-courses/products/copy-of-red-team-journeyman-course-rtjc" target="_blank" rel="noreferrer">https://store.k54.com/collections/all-courses/products/copy-of-red-team-journeyman-course-rtjc</a></p></li></ul>',13)])])}const f=t(o,[["render",s]]);export{h as __pageData,f as default};
